// VLM fast-path acceptance (#15 speed): the fixtures under src/ingest/fixtures
// are REAL outputs of the provider's native multimodal model reading rendered
// page PNGs (engine "vlm", qwen3.8-27b@fast-path — regenerated by hand while
// wiring server/vlm_parse.py). The chain asserted here is the SAME one the
// 精读 (Docling) path uses: route → binding → REAL experiment execution with
// the paper's own equations / initials / measurement table. If the model
// changes its output shape, these tests catch the drift before users do.
import { describe, expect, it } from 'vitest'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { routeAdapter } from './adapterRouter'
import { normalizeDocling } from '../ingest/doclingSchema'
import { executeSkill } from './executor'
import { buildPlan } from './playPlan'

function vlmDoc(name: string) {
  return normalizeDocling(JSON.parse(readFileSync(join('src/ingest/fixtures', `${name}.vlm.json`), 'utf8')))
}

describe('VLM fast-path fixtures → same route/binding/execution chain', () => {
  it('ODE paper: VLM-read formulas + initials drive a real integration', async () => {
    const doc = vlmDoc('ode-lotka-volterra')
    expect(doc.engine, 'fast-path provenance must be visible downstream').toBe('vlm')
    const d = routeAdapter(doc)
    expect(d.status).toBe('ok')
    expect(d.adapter, 'VLM dotted-latex (\\dot{x}, no spaces) must still route to ode').toBe('ode')
    if (d.adapter !== 'ode') return
    expect(d.binding.system?.states).toEqual(['x', 'y'])
    const initial = d.binding.conditions.find((c) => c.kind === 'initial') as { values: Record<string, number> }
    expect(initial.values).toEqual({ x: 2, y: 0.5 })
    // rhs derived the SAME way PaperDesk does (strip the dotted left-hand side)
    const rhs = d.binding.system!.equations.map((e) =>
      e.latex.slice(e.latex.indexOf('=') + 1).trim(),
    ) as [string, string]
    expect(rhs).toEqual(['x - xy', 'xy - y'])
    const out = await executeSkill<{ s0: number[]; period0: number | null }>(
      'ode.phase',
      {
        system: { kind: 'generic2', states: ['x', 'y'], rhs: { x: rhs[0], y: rhs[1] } },
        initialState: initial.values,
        tSpan: [0, 20],
      },
      buildPlan({ skill: 'ode.phase', goal: 'vlm fast-path acceptance: predator–prey' }),
    )
    if (out.status !== 'ok' || !out.run?.result) throw new Error(out.status)
    expect(out.run.result.s0.every((v) => v > 0)).toBe(true) // positive quadrant
    expect(out.run.result.period0).not.toBeNull() // closed orbit ⇒ periodic
  })

  it('fit paper: VLM pipe-table → structured {columns,rows} → 5 pairs + real sine run', async () => {
    const doc = vlmDoc('fit-sine-fit')
    const d = routeAdapter(doc)
    expect(d.status).toBe('ok')
    if (d.status !== 'ok' || d.adapter !== 'formula') return
    expect(d.binding.kind).toBe('fit')
    // the STRUCTURED path parsed the table (not the text heuristic): header
    // row skipped, exactly the paper's 5 measurement pairs survive
    expect(d.binding.dataPoints).toEqual([[0, 0], [0.5, 1.42], [1, 2], [1.5, 1.41], [2, 0.03]])
    // the paper's VLM-read latex (no trailing punctuation this time) executes
    const formula = doc.items.find((i) => i.kind === 'formula')
    const out = await executeSkill<{ peak: number }>(
      'formula.plot',
      {
        expression: formula!.latex!,
        parameters: ['a', 'b'],
        values: { a: 2, b: 1 },
        independent: 'x',
        range: [0, 6.4],
        samples: 65,
      },
      buildPlan({ skill: 'formula.plot', goal: 'vlm fast-path acceptance: sine fit' }),
    )
    if (out.status !== 'ok' || !out.run?.result) throw new Error(out.status)
    expect(out.run.result.peak).toBeCloseTo(2, 3) // |2·sin(x)| peaks at |a|
  })
})
